import { afterEach, expect, it, vi } from "vitest";
import { fireEvent, render, screen, within } from "@testing-library/react";
import { CopilotFunding } from "./copilot-funding";
import { changeComparisonSchema } from "@/lib/copilot-compare";
import { fundingResultSchema } from "@/lib/copilot-funding";
import { putFieldLabels } from "@/lib/put-fields";
import fixture from "@/test-fixtures/copilot-funding.json";

// Generated by the real Python comparison replay + funding calculation.
const source = changeComparisonSchema.parse(fixture.source);
const envelope = (data: unknown) => new Response(JSON.stringify({ data, error: null, meta: { request_id: "test" } }));
afterEach(() => vi.restoreAllMocks());
function fill() {
  fireEvent.click(screen.getByText("Compare this reduction with Put funding"));
  Object.entries(putFieldLabels).forEach(([key, label]) => fireEvent.change(screen.getByLabelText(`Funding ${label}`), {
    target: { value: String(fixture.request.put[key as keyof typeof fixture.request.put]) },
  }));
  fireEvent.change(screen.getByLabelText("Reduction fees (USD)"), { target: { value: String(fixture.request.sale_fees) } });
  screen.getAllByRole("checkbox").filter(box => !box.closest("section[aria-label=\"Optional account expiry scenarios\"]")).forEach(box => fireEvent.click(box));
}
function mount() {
  return render(<CopilotFunding source={source} token="test" protectedHoldings={fixture.request.protected_holdings} />);
}
function calculate() { fireEvent.click(screen.getByRole("button", { name: "Compare funding alternatives" })); }

it("uses a backend-generated response and requires all three confirmations", async () => {
  expect(fundingResultSchema.safeParse(fixture.result).success).toBe(true);
  const fetcher = vi.spyOn(globalThis, "fetch").mockResolvedValue(envelope(fixture.result));
  mount();
  expect(screen.getByRole("button", { name: "Compare funding alternatives", hidden: true })).toBeDisabled();
  expect(fetcher).not.toHaveBeenCalled();
  fill();
  const confirmations = screen.getAllByRole("checkbox").filter(box => !box.closest("section[aria-label=\"Optional account expiry scenarios\"]"));
  fireEvent.click(confirmations[1]);
  expect(screen.getByRole("button", { name: "Compare funding alternatives" })).toBeDisabled();
  fireEvent.click(confirmations[1]);
  calculate();
  await screen.findByLabelText("Funding alternatives");
  expect(JSON.parse(String(fetcher.mock.calls[0][1]?.body))).toEqual({ ...fixture.request, risk: null });
  expect(screen.getByText("Financing rules and account permissions are required before judging feasibility.")).toBeVisible();
  expect(screen.getByText("Cash does not cover the assumed obligation and reserves.")).toBeVisible();
  expect(screen.getByText(/interest cost and broker approval of additional borrowing are unknown/)).toBeVisible();
  const repay = screen.getByRole("heading", { name: "Reduce holding, repay debt, add Put" }).closest("section")!;
  expect(within(repay).getByText("$9,010.00")).toBeVisible();
  expect(within(repay).getAllByText("$8,811.00")).toHaveLength(2);
  const baseline = screen.getByRole("heading", { name: "Keep unchanged" }).closest("section")!;
  expect(within(baseline).queryByText("Assignment obligation")).not.toBeInTheDocument();
});

it.each(["account", "digest", "fees", "source", "protected", "put", "public_put"])("rejects a response with mismatched %s", async mismatch => {
  const result = fundingResultSchema.parse(fixture.result);
  if (mismatch === "account") result.portfolio_id = "22222222-2222-4222-8222-222222222222";
  if (mismatch === "digest") result.snapshot_digest = "wrong-snapshot";
  if (mismatch === "fees") result.assumptions.sale_fees += 1;
  if (mismatch === "source") result.source_result_id = "22222222-2222-4222-8222-222222222222";
  if (mismatch === "protected") result.assumptions.protected_holdings.push("SPY");
  if (mismatch === "put") result.alternatives[1].put!.assumptions.strike += 1;
  if (mismatch === "public_put") result.assumptions.put.strike += 1;
  vi.spyOn(globalThis, "fetch").mockResolvedValue(envelope(result));
  mount(); fill(); calculate();
  await screen.findByRole("alert");
  expect(screen.queryByLabelText("Funding alternatives")).not.toBeInTheDocument();
});

it.each(["Funding Strike (USD per share)", "Reduction fees (USD)"])("editing %s removes stale calculations and clears consent", async label => {
  vi.spyOn(globalThis, "fetch").mockResolvedValue(envelope(fixture.result));
  mount(); fill(); calculate();
  await screen.findByLabelText("Funding alternatives");
  fireEvent.change(screen.getByLabelText(label), { target: { value: "110" } });
  expect(screen.queryByLabelText("Funding alternatives")).not.toBeInTheDocument();
  screen.getAllByRole("checkbox").forEach(box => expect(box).not.toBeChecked());
  expect(screen.getByRole("button", { name: "Compare funding alternatives" })).toBeDisabled();
});

it("a protected-holdings change clears the result and confirmations", async () => {
  vi.spyOn(globalThis, "fetch").mockResolvedValue(envelope(fixture.result));
  const view = mount(); fill(); calculate();
  await screen.findByLabelText("Funding alternatives");
  view.rerender(<CopilotFunding source={source} token="test" protectedHoldings={["SGOV"]} />);
  expect(screen.queryByLabelText("Funding alternatives")).not.toBeInTheDocument();
  screen.getAllByRole("checkbox").forEach(box => expect(box).not.toBeChecked());
});

it("does not send incomplete input even if form validation is bypassed", async () => {
  const fetcher = vi.spyOn(globalThis, "fetch").mockResolvedValue(envelope(fixture.result));
  mount();
  fireEvent.click(screen.getByText("Compare this reduction with Put funding"));
  screen.getAllByRole("checkbox").filter(box => !box.closest("section[aria-label=\"Optional account expiry scenarios\"]")).forEach(box => fireEvent.click(box));
  fireEvent.submit(screen.getByRole("button", { name: "Compare funding alternatives" }).closest("form")!);
  expect(await screen.findByRole("alert")).toHaveTextContent("Complete all assumptions");
  expect(fetcher).not.toHaveBeenCalled();
});

it("rejects a missing no-action baseline or duplicate alternative", () => {
  const duplicate = structuredClone(fixture.result);
  duplicate.alternatives[0] = duplicate.alternatives[1];
  expect(fundingResultSchema.safeParse(duplicate).success).toBe(false);
  const tradedBaseline = structuredClone(fixture.result);
  tradedBaseline.alternatives[0].put = tradedBaseline.alternatives[1].put;
  expect(fundingResultSchema.safeParse(tradedBaseline).success).toBe(false);
});


it("blocks submission when optional risk is enabled but incomplete, including bypassed form validation", async () => {
  const fetcher = vi.spyOn(globalThis, "fetch");
  mount(); fill();
  fireEvent.click(screen.getByLabelText("Include explicit account-wide expiry price scenarios"));
  expect(screen.getByRole("button", { name: "Compare funding alternatives" })).toBeDisabled();
  fireEvent.submit(screen.getByRole("button", { name: "Compare funding alternatives" }).closest("form")!);
  expect(await screen.findByText("Complete or disable account-wide expiry scenarios.")).toBeVisible();
  expect(fetcher).not.toHaveBeenCalled();
});

it("rejects omitted account-wide calculations when risk assumptions were confirmed", () => {
  const value = { ...fixture.result, assumptions: { ...fixture.result.assumptions, risk: { scenarios: [{ label: "Stress", prices: { SPY: 0 } }], annual_borrowing_rate: null } }, account_risk: null };
  expect(fundingResultSchema.safeParse(value).success).toBe(false);
});
